package com.example.leavemanagement.people.application;
import com.example.leavemanagement.people.persistence.*; import com.example.leavemanagement.shared.api.DomainException; import com.example.leavemanagement.shared.security.CurrentActorProvider; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @Transactional(readOnly=true) public class EmployeeAdministrationQueryService { private final EmployeeProfileRepository employees; private final EmployeeAdministrationService service; private final CurrentActorProvider actors; public EmployeeAdministrationQueryService(EmployeeProfileRepository e,EmployeeAdministrationService s,CurrentActorProvider a){employees=e;service=s;actors=a;} private void admin(){if(!actors.require().hasRole("ADMINISTRATOR"))throw new DomainException(403,"ACCESS_DENIED","Administrator role is required");} public PageView list(int page,int size){admin();var p=employees.findAllByOrderByDisplayNameAsc(PageRequest.of(Math.max(0,page),Math.min(100,Math.max(1,size))));return new PageView(p.map(service::view).getContent(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages());} public record PageView(List<EmployeeAdministrationService.View> content,int page,int size,long totalElements,int totalPages){} }
